import fc from 'fast-check';
import { describe, expect, test } from 'vitest';
import { calcular } from '../src/calculos.js';
import { Decimal } from '../src/decimal.js';
import { firmar, verificarFirma } from '../src/firma.js';
import { emitir } from '../src/index.js';
import { validarXml } from '../src/validador/index.js';
import { generarXml, nombreArchivo } from '../src/xml.js';
import { desempaquetar } from '../src/zip.js';
import { SEMILLA, arbComprobante, arbItem } from './arbitrarios.js';
import { MUTACIONES, mutar } from './mutaciones.js';
import { comoOficial, consultarOraculo, oraculoDisponible } from './oraculo.js';

const opciones = { seed: SEMILLA, numRuns: 300 };

describe('invariantes de cálculo', () => {
  test('el total de valor de venta es la suma exacta de las líneas', () => {
    fc.assert(
      fc.property(arbComprobante, (c) => {
        const { lineas, totales } = calcular(c);
        expect(
          totales.valorVenta.comparar(Decimal.sumarTodos(lineas.map((l) => l.valorVenta))),
        ).toBe(0);
        expect(totales.igv.comparar(Decimal.sumarTodos(lineas.map((l) => l.igv)))).toBe(0);
        expect(totales.precioVenta.comparar(totales.valorVenta.sumar(totales.igv))).toBe(0);
        // Bases por tributo: particionan el valor de venta.
        expect(
          Decimal.sumarTodos(totales.porTributo.map((t) => t.base)).comparar(totales.valorVenta),
        ).toBe(0);
      }),
      opciones,
    );
  });

  test('el IGV de línea es el 18 % de la base, redondeado a céntimos (error ≤ 0.005)', () => {
    fc.assert(
      fc.property(arbItem, (item) => {
        const c = calcular({ ...base(), items: [item] });
        const [l] = c.lineas;
        if (!l) throw new Error('sin línea');
        const exacto = item.afectacion === '10' ? l.valorVenta.multiplicar('0.18') : Decimal.CERO;
        const error = l.igv.restar(exacto);
        expect(error.comparar('0.005')).toBeLessThanOrEqual(0);
        expect(error.comparar('-0.005')).toBeGreaterThanOrEqual(0);
        if (item.afectacion !== '10') expect(l.igv.esCero()).toBe(true);
      }),
      opciones,
    );
  });

  test('la suma de IGV de línea siempre cae dentro de la tolerancia de la regla 3291 (±1)', () => {
    fc.assert(
      fc.property(arbComprobante, (c) => {
        const { lineas, totales } = calcular(c);
        const base18 = Decimal.sumarTodos(
          lineas.filter((l) => l.tributo === '1000').map((l) => l.valorVenta),
        ).multiplicar('0.18');
        const diferencia = totales.igv.restar(base18);
        expect(diferencia.comparar(1)).toBeLessThanOrEqual(0);
        expect(diferencia.comparar(-1)).toBeGreaterThanOrEqual(0);
      }),
      opciones,
    );
  });
});

describe('roundtrip generar → firmar → empaquetar → desempaquetar → verificar → validar', () => {
  test('todo comprobante válido sobrevive el ciclo y queda aceptado', () => {
    fc.assert(
      fc.property(arbComprobante, (c) => {
        const { nombreZip, zip } = emitir(c);
        const abierto = desempaquetar(nombreZip, zip);
        if (!abierto.ok) throw new Error(abierto.detalle);
        expect(verificarFirma(abierto.xml).valida).toBe(true);
        expect(validarXml(abierto.xml, abierto.nombreXml)).toEqual({
          estado: 'aceptado',
          observaciones: [],
        });
      }),
      { ...opciones, numRuns: 100 },
    );
  });
});

describe.runIf(oraculoDisponible)('propiedades contra las reglas oficiales de SUNAT', () => {
  test('ninguna combinación válida es rechazada (ni por Chasqui ni por el XSL oficial)', () => {
    const muestras = fc.sample(arbComprobante, { seed: SEMILLA, numRuns: 200 });
    const casos = muestras.map((c) => ({
      tipo: c.tipo,
      nombre: `${nombreArchivo(c)}.xml`,
      xml: firmar(generarXml(calcular(c))),
    }));
    const oficiales = consultarOraculo(casos);
    casos.forEach((caso, i) => {
      expect(oficiales[i]).toEqual({ estado: 'ok', codigo: null, observaciones: [] });
      expect(comoOficial(validarXml(caso.xml, caso.nombre))).toEqual(oficiales[i]);
    });
  });

  test('ninguna inválida es aceptada: comprobantes y mutaciones aleatorias dan el veredicto oficial', () => {
    const arb = fc.tuple(arbComprobante, fc.constantFrom(...MUTACIONES));
    const muestras = fc
      .sample(arb, { seed: SEMILLA, numRuns: 600 })
      .filter(([c, m]) => !m.tipos || m.tipos.includes(c.tipo));
    const casos = muestras.map(([c, m]) => {
      const nombre = `${m.nombreArchivo ? m.nombreArchivo(nombreArchivo(c)) : nombreArchivo(c)}.xml`;
      const xml = generarXml(calcular(c));
      return {
        tipo: c.tipo,
        nombre,
        xml: m.aplicar ? mutar(xml, m.aplicar) : xml,
        mutacion: m.nombre,
      };
    });
    const oficiales = consultarOraculo(casos);
    const diferencias = casos
      .map((c, i) => ({
        mutacion: c.mutacion,
        nombre: c.nombre,
        oficial: oficiales[i],
        chasqui: comoOficial(validarXml(c.xml, c.nombre)),
      }))
      .filter((d) => JSON.stringify(d.oficial) !== JSON.stringify(d.chasqui));
    expect(diferencias).toEqual([]);
  });
});

function base() {
  return {
    tipo: '01' as const,
    serie: 'F001',
    correlativo: 1,
    fechaEmision: '2026-11-03',
    moneda: 'PEN' as const,
    emisor: {
      ruc: '20000000001',
      razonSocial: 'X S.A.C.',
      direccion: {
        ubigeo: '150101',
        departamento: 'LIMA',
        provincia: 'LIMA',
        distrito: 'LIMA',
        linea: 'AV 1',
      },
    },
    cliente: {
      tipoDocumento: '6' as const,
      numeroDocumento: '20000000002',
      nombre: 'CLIENTE S.A.',
    },
  };
}

test/conformidad.test.ts.source:
import { describe, expect, test } from 'vitest';
import { calcular } from '../src/calculos.js';
import type { Comprobante } from '../src/modelo.js';
import { validarXml } from '../src/validador/index.js';
import { generarXml, nombreArchivo } from '../src/xml.js';
import { boleta, factura, notaCredito, notaDebito } from './fixtures.js';
import { MUTACIONES, MUTACIONES_BORDE, mutar } from './mutaciones.js';
import { comoOficial, consultarOraculo, oraculoDisponible } from './oraculo.js';

const BASE: Record<string, () => Comprobante> = {
  factura,
  boleta,
  'nota de crédito': notaCredito,
  'nota de débito': notaDebito,
};

describe.runIf(oraculoDisponible)('conformidad con las reglas XSL oficiales de SUNAT', () => {
  test.each(Object.entries(BASE))('%s generada pasa sin errores ni observaciones', (_, crear) => {
    const c = crear();
    const xml = generarXml(calcular(c));
    const nombre = `${nombreArchivo(c)}.xml`;
    const [oficial] = consultarOraculo([{ tipo: c.tipo, nombre, xml }]);
    expect(oficial).toEqual({ estado: 'ok', codigo: null, observaciones: [] });
    expect(comoOficial(validarXml(xml, nombre))).toEqual(oficial);
  });

  // Prueba diferencial: cada mutación sobre cada tipo da el MISMO veredicto que la regla oficial.
  const casos = Object.entries(BASE).flatMap(([tipoNombre, crear]) => {
    const c = crear();
    return [...MUTACIONES, ...MUTACIONES_BORDE]
      .filter((m) => !m.tipos || m.tipos.includes(c.tipo))
      .map((m) => {
        const base = generarXml(calcular(c));
        const nombre = `${m.nombreArchivo ? m.nombreArchivo(nombreArchivo(c)) : nombreArchivo(c)}.xml`;
        const xml = m.aplicar ? mutar(base, m.aplicar) : base;
        return { titulo: `${tipoNombre}: ${m.nombre}`, tipo: c.tipo, nombre, xml };
      });
  });

  test('cada mutación dirigida da el mismo veredicto que el XSL oficial', () => {
    const oficiales = consultarOraculo(
      casos.map(({ tipo, nombre, xml }) => ({ tipo, nombre, xml })),
    );
    const diferencias = casos
      .map((c, i) => ({
        caso: c.titulo,
        oficial: oficiales[i],
        chasqui: comoOficial(validarXml(c.xml, c.nombre)),
      }))
      .filter((d) => JSON.stringify(d.oficial) !== JSON.stringify(d.chasqui));
    expect(diferencias).toEqual([]);
    // Las mutaciones tienen que ejercitar de verdad las reglas: la mayoría debe rechazar.
    expect(oficiales.filter((o) => o.estado === 'rechazo').length).toBeGreaterThan(
      casos.length * 0.6,
    );
  });

  // Contrato del validador: cada hallazgo cita la regla oficial (archivo y línea) de donde sale.
  // Las líneas se verificaron contra el XSL al portarlas; la instantánea impide que se pierdan.
  test('cada hallazgo cita su regla de origen en el XSL oficial', async () => {
    const citas = Object.fromEntries(
      casos.map((c) => {
        const v = validarXml(c.xml, c.nombre);
        const fmt = (h: { codigo: string; fuente: string }) => `${h.codigo} @ ${h.fuente}`;
        return [c.titulo, [...v.observaciones.map(fmt), ...(v.error ? [fmt(v.error)] : [])]];
      }),
    );
    await expect(JSON.stringify(citas, null, 2)).toMatchFileSnapshot('__snapshots__/citas.json');
  });
});

test/conformidad-resumenes.test.ts.source:
import fc from 'fast-check';
import { describe, expect, test } from 'vitest';
import { calcular } from '../src/calculos.js';
import { firmar } from '../src/firma.js';
import {
  generarBaja,
  generarResumen,
  lineaResumen,
  nombreBaja,
  nombreResumen,
  type ComunicacionBaja,
  type ResumenDiario,
} from '../src/resumenes.js';
import { validarXml } from '../src/validador/index.js';
import { SEMILLA, arbComprobante } from './arbitrarios.js';
import { boleta, emisor } from './fixtures.js';
import { mutar } from './mutaciones.js';
import { comoOficial, consultarOraculo, oraculoDisponible } from './oraculo.js';

const baja = (): ComunicacionBaja => ({
  emisor,
  correlativo: 1,
  fechaComunicacion: '2026-11-03',
  fechaReferencia: '2026-11-02',
  lineas: [
    { tipo: '01', serie: 'F001', numero: 1, motivo: 'Error en la operación' },
    { tipo: '07', serie: 'F001', numero: 2, motivo: 'Nota emitida por error' },
  ],
});

const resumen = (): ResumenDiario => {
  const b1 = calcular(boleta());
  const b2 = calcular({ ...boleta(), correlativo: 2 });
  return {
    emisor,
    correlativo: 1,
    fechaResumen: '2026-11-03',
    fechaReferencia: '2026-11-02',
    moneda: 'PEN',
    lineas: [lineaResumen(b1, '1'), lineaResumen(b2, '3')],
  };
};

const raiz = '/*';
const linea = `${raiz}/*[local-name()='VoidedDocumentsLine' or local-name()='SummaryDocumentsLine'][1]`;
const cada = (expr: string, f: (e: Element) => void) => (sel: (x: string) => Element[]) => {
  sel(expr).forEach(f);
};
const texto = (v: string) => (e: Element) => {
  e.textContent = v;
};
const quitar = (e: Element) => e.parentNode?.removeChild(e);

interface MutacionResumen {
  nombre: string;
  tipos?: ('RA' | 'RC')[];
  nombreArchivo?: (n: string) => string;
  aplicar?: (sel: (x: string) => Element[]) => void;
}

const MUTACIONES: MutacionResumen[] = [
  { nombre: 'UBLVersionID 2.1', aplicar: cada(`${raiz}/cbc:UBLVersionID`, texto('2.1')) },
  { nombre: 'sin UBLVersionID', aplicar: cada(`${raiz}/cbc:UBLVersionID`, quitar) },
  { nombre: 'CustomizationID 2.0', aplicar: cada(`${raiz}/cbc:CustomizationID`, texto('2.0')) },
  {
    nombre: 'ID distinto al nombre',
    aplicar: cada(`${raiz}/cbc:ID`, (e) => (e.textContent = `${e.textContent}9`)),
  },
  {
    nombre: 'fecha distinta a la del nombre',
    aplicar: cada(`${raiz}/cbc:IssueDate`, texto('2026-11-04')),
  },
  { nombre: 'sin IssueDate', tipos: ['RA'], aplicar: cada(`${raiz}/cbc:IssueDate`, quitar) },
  {
    nombre: 'sin ReferenceDate',
    tipos: ['RA'],
    aplicar: cada(`${raiz}/cbc:ReferenceDate`, quitar),
  },
  { nombre: 'RUC del nombre distinto', nombreArchivo: (n) => n.replace(/^\d{11}/, '20999999999') },
  {
    nombre: 'sin RUC del emisor',
    aplicar: cada(`${raiz}/cac:AccountingSupplierParty/cbc:CustomerAssignedAccountID`, quitar),
  },
  {
    nombre: 'tipo de documento del emisor 1',
    aplicar: cada(`${raiz}/cac:AccountingSupplierParty/cbc:AdditionalAccountID`, texto('1')),
  },
  {
    nombre: 'razón social de 2 caracteres',
    aplicar: cada(
      `${raiz}/cac:AccountingSupplierParty/cac:Party/cac:PartyLegalEntity/cbc:RegistrationName`,
      texto('AB'),
    ),
  },
  { nombre: 'LineID 0', aplicar: cada(`${linea}/cbc:LineID`, texto('0')) },
  {
    nombre: 'LineID duplicado',
    aplicar: (sel) => {
      const [a, b] = sel(`${raiz}/*/cbc:LineID`);
      if (a && b) b.textContent = a.textContent;
    },
  },
  { nombre: 'LineID con cero inicial', aplicar: cada(`${linea}/cbc:LineID`, texto('01')) },
  {
    nombre: 'tipo de documento 03 en baja',
    tipos: ['RA'],
    aplicar: cada(`${linea}/cbc:DocumentTypeCode`, texto('03')),
  },
  {
    nombre: 'tipo de documento 01 en resumen',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cbc:DocumentTypeCode`, texto('01')),
  },
  {
    nombre: 'serie de boleta en baja de factura',
    tipos: ['RA'],
    aplicar: cada(`${linea}/*[local-name()='DocumentSerialID']`, texto('B001')),
  },
  {
    nombre: 'serie inválida en baja',
    tipos: ['RA'],
    aplicar: cada(`${linea}/*[local-name()='DocumentSerialID']`, texto('X1')),
  },
  {
    nombre: 'número de 9 dígitos en baja',
    tipos: ['RA'],
    aplicar: cada(`${linea}/*[local-name()='DocumentNumberID']`, texto('123456789')),
  },
  {
    nombre: 'motivo de baja de 2 caracteres',
    tipos: ['RA'],
    aplicar: cada(`${linea}/*[local-name()='VoidReasonDescription']`, texto('XY')),
  },
  {
    nombre: 'documento repetido en la baja',
    tipos: ['RA'],
    aplicar: (sel) => {
      const [a, b] = sel(`${raiz}/*[local-name()='VoidedDocumentsLine']`);
      if (a && b) b.parentNode?.replaceChild(a.cloneNode(true), b);
    },
  },
  {
    nombre: 'sin condición del ítem',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cac:Status/cbc:ConditionCode`, quitar),
  },
  {
    nombre: 'condición fuera del catálogo 19',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cac:Status/cbc:ConditionCode`, texto('9')),
  },
  {
    nombre: 'serie-número de factura en resumen',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cbc:ID`, texto('F001-1')),
  },
  {
    nombre: 'total con 3 decimales',
    tipos: ['RC'],
    aplicar: cada(
      `${linea}/*[local-name()='TotalAmount']`,
      (e) => (e.textContent = `${e.textContent}1`),
    ),
  },
  {
    nombre: 'moneda distinta en un monto',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cac:TaxTotal/cbc:TaxAmount`, (e) => {
      e.setAttribute('currencyID', 'USD');
    }),
  },
  {
    nombre: 'total mayor a 700 sin cliente',
    tipos: ['RC'],
    aplicar: (sel) => {
      sel(`${linea}/*[local-name()='TotalAmount']`).forEach(texto('800.00'));
      sel(`${linea}/cac:AccountingCustomerParty`).forEach(quitar);
    },
  },
  {
    nombre: 'cliente con RUC de 10 dígitos',
    tipos: ['RC'],
    aplicar: (sel) => {
      sel(`${linea}/cac:AccountingCustomerParty/cbc:AdditionalAccountID`).forEach(texto('6'));
      sel(`${linea}/cac:AccountingCustomerParty/cbc:CustomerAssignedAccountID`).forEach(
        texto('2000000000'),
      );
    },
  },
  {
    nombre: 'cliente con DNI de 7 dígitos',
    tipos: ['RC'],
    aplicar: cada(
      `${linea}/cac:AccountingCustomerParty/cbc:CustomerAssignedAccountID`,
      texto('1234567'),
    ),
  },
  {
    nombre: 'cliente con documento fuera del catálogo',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cac:AccountingCustomerParty/cbc:AdditionalAccountID`, texto('Z')),
  },
  {
    nombre: 'pago con monto 0',
    tipos: ['RC'],
    aplicar: cada(`${linea}/*[local-name()='BillingPayment']/cbc:PaidAmount`, texto('0.00')),
  },
  {
